SELECT id, title, status, details, due_date AS dueDate, auto_carry_over AS autoCarryOver, is_daily AS daily, has_flag AS hasFlag, category_id AS categoryId, overdue_behavior AS overdueBehavior, sort_order AS sortOrder FROM todos
AND status = #{status}
AND title LIKE CONCAT ('%', #{title}, '%')
AND category_id = #{categoryId}
AND has_flag = #{hasFlag}
AND is_daily = #{daily}
AND due_date = #{dueDate}
AND due_date IS NOT NULL
ORDER BY CASE WHEN status = 'INCOMPLETE' THEN 1 ELSE 2 END ASC, CASE WHEN sort_order IS NULL THEN 1 ELSE 0 END ASC, sort_order ASC, id DESC

mapper.update:
UPDATE todos
SET
  sort_order = #{sortOrder}
WHERE
  id = #{id}

UPDATE todos
SET
  status = #{status}
WHERE
  id = #{id}

UPDATE todos
SET
  category_id = #{categoryId}
WHERE
  id = #{id}
